// Generated by app-portfolio/scripts/build_arcade.py. Do not edit: change the template there.
import { expect, test, type Page } from '@playwright/test';
import rawCatalog from '../src/arcade/catalog.json';

const APP = 'worthit';
type Game = { id: string; mechanic: string; tier: string; flagship?: boolean; pack: { file: string } | null };
const catalog = rawCatalog as unknown as { games: Game[] };
// Playwright runs from the app root.
const fixtures = 'e2e/fixtures/arcade';

async function setup(page: Page, served: string[] = []) {
  // Skip the first-run intro, and serve game packs from local copies instead of kaoticchainz.com.
  await page.addInitScript((app) => {
    if (!localStorage.getItem(`${app}.prefs`)) localStorage.setItem(`${app}.prefs`, JSON.stringify({ state: { onboarded: true }, version: 1 }));
  }, APP);
  await page.route('https://kaoticchainz.com/arcade/**', async (route) => {
    const rel = new URL(route.request().url()).pathname.replace(/^\/arcade\//, '');
    served.push(rel);
    await route.fulfill({ path: `${fixtures}/${rel}`, contentType: 'application/json' });
  });
}

async function openArcade(page: Page) {
  await page.goto('/arcade');
  // Apps with a lock screen (Granny's Vault) protect the arcade too.
  const unlock = page.getByTestId('unlock');
  await expect(page.getByTestId('arcade').or(unlock)).toBeVisible();
  if (await unlock.isVisible()) await unlock.click();
  await expect(page.getByTestId('arcade')).toBeVisible();
}

async function playAndEnd(page: Page) {
  await page.getByTestId('game-start').click();
  await expect(page.getByTestId('game-score')).toBeVisible({ timeout: 8000 });
  await page.getByTestId('game-end').click();
  await expect(page.getByTestId('game-final')).toBeVisible();
}

test('arcade lists at least 8 games; the flagship plays and pays out', async ({ page }) => {
  const errors: string[] = [];
  page.on('pageerror', (e) => errors.push(e.message));
  await setup(page);
  await openArcade(page);
  expect(catalog.games.length).toBeGreaterThanOrEqual(8);
  for (const g of catalog.games) await expect(page.getByTestId(`game-${g.id}`)).toBeAttached();
  const flagship = catalog.games.find((g) => g.flagship)!;
  await page.getByTestId(`game-${flagship.id}`).click();
  await playAndEnd(page);
  await expect(page.getByTestId('game-earned')).toContainText('+');
  await page.getByTestId('game-exit').click();
  await expect(page.getByTestId('arcade-balance')).not.toHaveText(/^0 /);
  expect(errors).toEqual([]);
});

test('free games download on demand, once', async ({ page }) => {
  const served: string[] = [];
  await setup(page, served);
  await openArcade(page);
  const g = catalog.games.find((x) => x.tier === 'free' && !x.flagship && x.mechanic !== 'route')!;
  test.skip(!g, 'no downloadable free game');
  await expect(page.getByTestId(`game-${g.id}`)).toContainText('Download');
  await page.getByTestId(`game-${g.id}`).click();
  await expect(page.getByTestId('game-start')).toBeVisible();
  expect(served).toEqual([g.pack!.file]);
  await openArcade(page);
  await expect(page.getByTestId(`game-${g.id}`)).toContainText('Downloaded');
});

test('KC Arcade games are locked until bought, then stay unlocked', async ({ page }) => {
  await setup(page);
  await openArcade(page);
  const g = catalog.games.find((x) => x.tier === 'arcade' && x.mechanic !== 'route')!;
  await page.getByTestId(`game-${g.id}`).click();
  await expect(page.getByTestId('paywall')).toBeVisible();
  await expect(page.getByTestId('paywall-buy')).toContainText('£14.99');
  await page.getByTestId('paywall-buy').click();
  await page.getByTestId('paywall-done').click();
  await page.getByTestId(`game-${g.id}`).click();
  await expect(page.getByTestId('game-start')).toBeVisible();
});
